INSERT INTO `notes` (`id`, `title`, `content`, `color`, `pos_x`, `pos_y`, `z_index`, `created_at`, `updated_at`) VALUES ('2', 'واریز و برداشت محمدرضا', '+ طلب محمدرضا بابت دکور 87 میلیون\n-  واریزی حاج غلام 50 میلیون \n= مانده حساب محمدرضا 37 میلیون\n+ خرید پلاستیک برای مغازه 2.500.000 میلیون', '#ffadad', '197', '37', '102', '2026-10-03 09:09:12', '2026-10-04 11:54:06');
INSERT INTO `notes` (`id`, `title`, `content`, `color`, `pos_x`, `pos_y`, `z_index`, `created_at`, `updated_at`) VALUES ('4', 'برداشت از حساب مغازه', '- انتقال وجه 50 میلیون برای حاج غلام صفری\n+ حاج غلام 50 میلیون به حساب محمدرضا واریز کرد\n- برداشت بابت وام سپه حمید 7.350.000\n- پرداخت مالیات  1.198.000\n- برداشت 2.775.000 تومان روغن ماشین بحرینی \n- انتقال برای عباس بازرگان 5 میلیون تومان\n- خرید دوربین مدار بسته 24.000.000', '#fff3a3', '551', '37', '102', '2026-10-03 09:32:27', '2026-10-04 09:58:25');
